declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$uid=(int)$_POST['user_id'];$enabled=(string)$_POST['action']==='enable';$target=$db->one('SELECT id,is_admin FROM users WHERE id=?',[$uid]);if(!$target||(bool)$target['is_admin']!==true)throw new RuntimeException('Break-glass może dotyczyć tylko administratora.');$db->execute('UPDATE users SET break_glass=?,inactive_lock_exempt=? WHERE id=?',[$enabled?1:0,$enabled?1:0,$uid]);if($enabled&&!$db->one('SELECT 1 FROM mfa_methods WHERE user_id=? AND enabled=1',[$uid])&&!$db->one('SELECT 1 FROM webauthn_credentials WHERE user_id=? AND revoked_at IS NULL',[$uid]))$db->execute("INSERT INTO required_actions(user_id,action_type,payload_json) SELECT ?,'setup_mfa',JSON_OBJECT('reason','break_glass') WHERE NOT EXISTS(SELECT 1 FROM required_actions WHERE user_id=? AND action_type='setup_mfa' AND status='pending')",[$uid,$uid]);$audit->write('admin.break_glass.changed','success',(int)$admin['id'],$uid,null,null,['enabled'=>$enabled]);$message='<div class="alert success">Zapisano.</div>';}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}$rows='';foreach($db->all("SELECT id,name,email,break_glass,last_login_at FROM users WHERE is_admin=1 ORDER BY break_glass DESC,name")as$u)$rows.='<tr><td>'.Web::e($u['name']).'</td><td>'.Web::e($u['email']).'</td><td>'.((bool)$u['break_glass']?'<span class="badge warning">Break-glass</span>':'Zwykły admin').'</td><td>'.Web::e($u['last_login_at']?:'—').'</td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><button name="action" value="'.((bool)$u['break_glass']?'disable':'enable').'">'.((bool)$u['break_glass']?'Wyłącz break-glass':'Oznacz jako break-glass').'</button></form></td></tr>';$content='<div class="page-head"><div><h1>Break-glass accounts</h1><p>Awaryjne konta administracyjne są wyłączone z auto-locku i wymagają MFA przed operacjami administracyjnymi.</p></div></div>'.$message.'<div class="alert warning">Konta break-glass powinny mieć unikalne, silne poświadczenia i być używane wyłącznie awaryjnie. Zmiany są audytowane.</div><div class="table-wrap"><table><thead><tr><th>Administrator</th><th>E-mail</th><th>Tryb</th><th>Ostatnie logowanie</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div>';Web::page('Break-glass',$content,$admin);
